package doctor

import (
	"os/exec"
	"syscall"
)

// setNewProcessGroup makes cmd the leader of a new process group, so
// killProcessGroupOnTimeout below can kill the whole tree a sandboxed hook
// spawns — not just the direct child exec.CommandContext tracks (S4). A
// hook that backgrounds a child (`cmd &`, nohup) would otherwise leave that
// child running past both sandboxTimeout and the sandbox's temp-dir
// cleanup, in a directory that no longer exists.
func setNewProcessGroup(cmd *exec.Cmd) {
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
}

// killProcessGroupOnTimeout returns a cmd.Cancel func that SIGKILLs cmd's
// entire process group (the negative-PID form of kill(2)) rather than only
// cmd's direct PID, which is exec.CommandContext's default Cancel
// behavior and does not reach a backgrounded grandchild.
func killProcessGroupOnTimeout(cmd *exec.Cmd) func() error {
	return func() error {
		if cmd.Process == nil {
			return nil
		}
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
}

